import{_ as e,o as a,c as i,a0 as s}from"./chunks/framework.C0WKPwzJ.js";const k=JSON.parse('{"title":"Autodevelop CLI","description":"Sign in on this machine, install the organization pack, and mint a short-lived GitHub App token.","frontmatter":{"title":"Autodevelop CLI","description":"Sign in on this machine, install the organization pack, and mint a short-lived GitHub App token."},"headers":[],"relativePath":"cli.md","filePath":"cli.md","lastUpdated":1788171427000}'),n={name:"cli.md"};function o(l,t,h,d,p,r){return a(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="autodevelop-cli" tabindex="-1">Autodevelop CLI <a class="header-anchor" href="#autodevelop-cli" aria-label="Permalink to &quot;Autodevelop CLI&quot;">​</a></h1><p>Copyright (c) 2026 Devrecated.</p><p>The customer CLI authorizes a developer machine for a paid Autodevelop organization. Cursor still loads the kit as a user-scope plugin (<a href="./install">Install</a>).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @devrecated/autodevelop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @devrecated/autodevelop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @devrecated/autodevelop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logout</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @devrecated/autodevelop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @devrecated/autodevelop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--slug </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">instanc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @devrecated/autodevelop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> token</span></span></code></pre></div><p>In a kit checkout the same commands are <code>pnpm autodevelop …</code>.</p><p><code>AUTODEVELOP_HOST</code> selects the host when you are not on the default production host. <code>AUTODEVELOP_TOKEN</code> wins over the credentials file when set. Do not put the token in <code>config.json</code>.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>login</code></td><td>Opens a device-code page. After you approve this machine, stores a credential and installs the organization pack</td></tr><tr><td><code>logout</code></td><td>Removes the stored credential on this machine. Environment variables are unchanged</td></tr><tr><td><code>status</code></td><td>Shows whether this machine is signed in, the host, and the local pack version</td></tr><tr><td><code>install</code></td><td>Installs or refreshes the organization pack into the current repository</td></tr><tr><td><code>github token</code></td><td>Mints a short-lived GitHub App installation token for <code>gh</code>. Prints expiry and account, not the token</td></tr></tbody></table><h2 id="paywall" tabindex="-1">Paywall <a class="header-anchor" href="#paywall" aria-label="Permalink to &quot;Paywall&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>What happens</th></tr></thead><tbody><tr><td>No credential</td><td>Device login opens. No pack. No GitHub token.</td></tr><tr><td>Signed in, organization not active</td><td>Stop. <code>Your billing has expired</code>. No files written.</td></tr><tr><td>Active subscription</td><td>Login, pack install, and GitHub token mint run.</td></tr></tbody></table><p>There is no public signup. An operator invites the owner, then the owner signs in.</p><h2 id="github-token" tabindex="-1">GitHub token <a class="header-anchor" href="#github-token" aria-label="Permalink to &quot;GitHub token&quot;">​</a></h2><p>Connect the App first (<a href="./github">GitHub App</a>). Then:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> autodevelop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> token</span></span></code></pre></div><p>Export <code>GH_TOKEN</code> yourself if you want <code>gh</code> to use it for that process. The CLI does not print the token. Do not persist it in <code>config.json</code>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./install">Install</a></li><li><a href="./github">GitHub App</a></li><li><a href="./workflows/initial-setup">Initial setup</a></li><li><a href="./workflows/when-something-breaks">When something breaks</a></li></ul>`,17)])])}const u=e(n,[["render",o]]);export{k as __pageData,u as default};
